using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace Aurora {
public partial class MainWindow {
    void DriverCatalogCard(Func<DriverRecord> selectedDevice){
        var card=Card(T("Outras fontes de drivers","Additional driver sources"),T("Selecione um dispositivo em Drivers instalados. O OuO consulta o Catálogo Microsoft e os catálogos oficiais Dell ou HP para o fabricante correspondente. Os pacotes são conferidos pelo hardware, sistema e assinatura antes de instalar.","Select a device under Installed drivers. OuO checks Microsoft Catalog and Dell or HP official catalogs for the matching manufacturer. Packages are checked by hardware, OS and signature before installation."));
        var microsoft=Choice(card,T("Catálogo Microsoft — pesquisa por hardware","Microsoft Catalog — hardware search"),true,true);var oem=Choice(card,T("Catálogo do fabricante — Dell/HP","Manufacturer catalog — Dell/HP"),true,true);var older=Choice(card,T("Mostrar também outras versões para reinstalação","Also show other versions for reinstallation"),true,false);
        var summary=Text(T("Escolha um dispositivo e clique em Consultar fontes.","Choose a device and select Check sources."),13,Muted);card.Children.Add(summary);var list=new ListBox{Height=260,Background=Surface,Foreground=Ink,BorderBrush=Muted,Visibility=Visibility.Collapsed};ScrollViewer.SetHorizontalScrollBarVisibility(list,ScrollBarVisibility.Disabled);list.HorizontalContentAlignment=HorizontalAlignment.Stretch;card.Children.Add(list);var checks=new Dictionary<CatalogDriver,CheckBox>();
        var allowWithout=Choice(card,T("Continuar se o Windows não puder criar ponto de restauração","Continue if Windows cannot create a restore point"),true,false);
        var report=Input("");report.IsReadOnly=true;report.AcceptsReturn=true;report.Height=170;report.TextWrapping=TextWrapping.Wrap;report.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;AttachResult(card,report);
        Row(card,Button(T("Consultar fontes","Check sources"),()=>{var device=selectedDevice();if(device==null){ShowToast(T("Selecione primeiro um dispositivo na lista instalada.","Select an installed device first."));return;}bool ms=microsoft.IsChecked==true,vendor=oem.IsChecked==true,all=older.IsChecked==true;if(!ms&&!vendor)return;List<CatalogDriver> found=null;var notes=new List<string>();
            Work(T("Consultar catálogos de drivers","Check driver catalogs"),()=>{int job=workerJobId;found=DriverCatalogs.Search(device,ms,vendor,all,name=>ReportStage(T("Consultando ","Checking ")+name,job),notes);return "OK • "+found.Count+T(" candidato(s) encontrado(s)."," candidate(s) found.")+"\n"+String.Join("\n",notes);},r=>{checks.Clear();list.Items.Clear();foreach(var item in found??new List<CatalogDriver>()){var box=new CheckBox{Content=new TextBlock{Text=item.ToString(),TextWrapping=TextWrapping.Wrap},Foreground=Ink,Tag=item,Margin=new Thickness(5),ToolTip=item.Details};list.Items.Add(box);checks[item]=box;}list.Visibility=list.Items.Count>0?Visibility.Visible:Visibility.Collapsed;summary.Text=device.Name+"\n"+r;summary.Foreground=OutcomeBrush(r);});
        }),Button(T("Baixar e instalar marcados","Download and install checked"),()=>{var chosen=checks.Where(x=>x.Value.IsChecked==true).Select(x=>x.Key).ToArray();if(chosen.Length==0)return;if(chosen.GroupBy(x=>x.Device.DeviceId,StringComparer.OrdinalIgnoreCase).Any(g=>g.Count()>1)){ShowNotice(T("Escolha apenas uma versão por dispositivo.","Choose only one version per device."));return;}if(!RequireAdmin())return;if(!Confirm(T("Baixar, validar e instalar estes drivers? O OuO extrairá os pacotes e usará somente INF compatível e catálogo assinado. Pode ser necessário reiniciar.\n\n","Download, validate and install these drivers? OuO extracts packages and uses matching INF files and signed catalogs. Restart may be required.\n\n")+String.Join("\n",chosen.Select(x=>x.Source+" • "+x.Title))))return;bool proceed=allowWithout.IsChecked==true;
            Work(T("Instalar drivers de catálogos","Install catalog drivers"),()=>{int job=workerJobId;var point=Runner.PS("Checkpoint-Computer -Description 'OuO catalog drivers' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop;Write-Output 'Restore point created'",120000);if(point.Code!=0&&!proceed)return "ERROR • "+T("O ponto de restauração não foi criado. Nenhum driver foi instalado. ","Restore point was not created. No driver installed. ")+point.Output;var result=new List<string>();if(point.Code!=0)result.Add(T("Aviso • instalação autorizada sem novo ponto: ","Warning • installation authorized without a new point: ")+point.Output);foreach(var item in chosen)try{result.Add(DriverCatalogs.Install(item,machine==null?0:machine.Build,stage=>ReportStage(stage,job)));}catch(Exception ex){result.Add("ERROR • "+item.Title+" • "+ex.Message);}return String.Join("\n\n",result);},r=>{report.Text=r;DriverInventory.Invalidate();Action refresh;if(pageRefreshActions.TryGetValue("drivers",out refresh))refresh();});
        }));
    }
}
}
